const VIEWS={brf:renderBRF,st:renderST,trf:renderTRF,tea:renderTEA,mnt:renderMNT,lab:renderLAB,ont:renderONT,dat:renderDAT,gov:renderGOV};
let cur="brf";
function show(v){if(!VIEWS[v])v="brf";cur=v;document.querySelectorAll(".view").forEach(s=>s.hidden=s.id!=="v-"+v);document.querySelectorAll(".nav button,.mnav button").forEach(b=>{if(b.dataset.view===v)b.setAttribute("aria-current","page");else b.removeAttribute("aria-current");});VIEWS[v]();try{history.replaceState(null,"","#"+v);}catch(e){}window.scrollTo(0,0);tip.hidden=true;}
const rerender=()=>{const y=window.scrollY;VIEWS[cur]();window.scrollTo(0,y);};
document.querySelectorAll(".nav button,.mnav button").forEach(b=>b.addEventListener("click",()=>show(b.dataset.view)));
document.addEventListener("click",e=>{const t=e.target;
  const go=t.closest("[data-go]");if(go){show(go.dataset.go);return;}
  if(t.closest("[data-pres]")||t.id==="pres-open"){openPres();return;}
  const dep=t.closest("[data-dep]");if(dep){st.dept=dep.dataset.dep;store.set("mi.dept",st.dept);if(cur!=="st")show("st");else rerender();return;}
  const hx=t.closest("[data-hex]");if(hx&&HEX){st.dept=HEX.cells[+hx.dataset.hex].dep.c;rerender();return;}
  const th=t.closest("[data-th]");if(th){st.th=th.dataset.th;if(cur!=="tea")show("tea");else rerender();return;}
  const fl=t.closest("[data-fl]");if(fl){st.fl=+fl.dataset.fl;rerender();return;}
  const md=t.closest("[data-mdl]");if(md){st.mdl=md.dataset.mdl;rerender();return;}
  const on=t.closest("[data-ont]");if(on){st.ont=on.dataset.ont;rerender();return;}
  ["hz","model","layer"].forEach(k=>{const b=t.closest("[data-"+k+"]");if(b){st[k]=k==="hz"?+b.dataset[k]:b.dataset[k];rerender();}});
});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches&&e.target.matches(".it,.tile,.nd")){e.preventDefault();e.target.click();}});
document.addEventListener("input",e=>{if(e.target.id==="st-week"){st.week=+e.target.value;rerender();}});

